1	package api
2	
3	// Concurrent regression tests for the public HTTP surface. Unlike the store
4	// level concurrency test, these drive a real HTTP server (one service instance
5	// backed by a healthy on-disk SQLite store) through POST /v1/net-policies and
6	// GET /v1/net-policies so the assertions cover the externally visible results:
7	// status codes, response bodies, ordering and the published error shape.
8	
9	import (
10		"encoding/json"
11		"fmt"
12		"io"
13		"net/http"
14		"net/http/httptest"
15		"path/filepath"
16		"reflect"
17		"runtime"
18		"strings"
19		"sync"
20		"testing"
21		"time"
22	
23		"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
24	)
25	
26	const (
27		clientTimeout = 10 * time.Second
28		// roundBudget bounds every wait inside one round (reader startup, the
29		// whole write burst, reader shutdown): waiting longer than ten seconds
30		// fails the round rather than hanging the suite.
31		roundBudget = 10 * time.Second
32	)
33	
34	const (
35		raceNamespace = "payments"
36		raceName      = "race-policy"
37		raceLabel     = "tier=backend"
38	)
39	
40	// The two racing groups are identical except for one legal plugin string value
41	// ("mode"); "zone" and the rules stay identical across the groups.
42	const raceBodyA = `{
43		"namespace": "payments",
44		"name": "race-policy",
45		"label": "tier=backend",
46		"rules": [{"direction": "ingress", "action": "deny", "ports": [80, 100]}],
47		"pluginParams": {"mode": "enforce", "zone": "east"}
48	}`
49	
50	// Equivalent content for group A: top-level members, rule members and
51	// pluginParams members all appear in a different order.
52	const raceBodyAReordered = `{
53		"pluginParams": {"zone": "east", "mode": "enforce"},
54		"rules": [{"ports": [80, 100], "action": "deny", "direction": "ingress"}],
55		"label": "tier=backend",
56		"name": "race-policy",
57		"namespace": "payments"
58	}`
59	
60	const raceBodyB = `{
61		"namespace": "payments",
62		"name": "race-policy",
63		"label": "tier=backend",
64		"rules": [{"direction": "ingress", "action": "deny", "ports": [80, 100]}],
65		"pluginParams": {"mode": "audit", "zone": "east"}
66	}`
67	
68	// Equivalent content for group B with object members reordered.
69	const raceBodyBReordered = `{
70		"pluginParams": {"zone": "east", "mode": "audit"},
71		"rules": [{"ports": [80, 100], "action": "deny", "direction": "ingress"}],
72		"label": "tier=backend",
73		"name": "race-policy",
74		"namespace": "payments"
75	}`
76	
77	// Same identity with a null plugin member racing with the legal submissions:
78	// always invalid input, regardless of how far the other requests have got.
79	const raceBodyNullMember = `{
80		"namespace": "payments",
81		"name": "race-policy",
82		"label": "tier=backend",
83		"rules": [{"direction": "ingress", "action": "deny", "ports": [80, 100]}],
84		"pluginParams": {"zone": "east", "mode": null}
85	}`
