481	// Every legal string value is preserved verbatim, including the empty string,
482	// whitespace-only strings, non-ASCII text and the literal string "null".
483	func TestPostNetPolicyPreservesLegalPluginParamValues(t *testing.T) {
484		cases := []struct {
485			name       string
486			identity   string
487			paramsJSON string
488			want       map[string]any
489		}{
490			{"empty object", "empty-obj", `{}`, map[string]any{}},
