521	// An idempotent retry containing empty/non-ASCII values returns 200 with the
522	// original record regardless of object key order, consumes no order, and the
523	// next brand-new identity keeps the expected sequence.
524	func TestPostNetPolicyIdempotentRetryWithSpecialValues(t *testing.T) {
525		router, _ := newTestRouter(t)
526		seed := policyBody("payments", "default-deny", "tier=backend", `{"zone": "华北", "mode": ""}`)
527		if rec := doRequest(router, http.MethodPost, "/v1/net-policies", seed); rec.Code != http.StatusCreated {
528			t.Fatalf("seed status = %d: %s", rec.Code, rec.Body.String())
529		}
530	
531		reordered := policyBody("payments", "default-deny", "tier=backend", `{"mode": "", "zone": "华北"}`)
532		retry := doRequest(router, http.MethodPost, "/v1/net-policies", reordered)
533		if retry.Code != http.StatusOK {
534			t.Fatalf("retry status = %d, want %d: %s", retry.Code, http.StatusOK, retry.Body.String())
535		}
536		var body map[string]any
537		if err := json.Unmarshal(retry.Body.Bytes(), &body); err != nil {
538			t.Fatalf("decode: %v", err)
539		}
540		if body["order"] != float64(1) {
541			t.Fatalf("retry order = %v, want original 1", body["order"])
542		}
543		wantParams := map[string]any{"mode": "", "zone": "华北"}
544		if !reflect.DeepEqual(body["pluginParams"], wantParams) {
545			t.Fatalf("retry pluginParams = %v, want %v", body["pluginParams"], wantParams)
546		}
547	
548		next := doRequest(router, http.MethodPost, "/v1/net-policies",
549			policyBody("payments", "after-retry", "tier=backend", `{}`))
550		if next.Code != http.StatusCreated {
551			t.Fatalf("next status = %d: %s", next.Code, next.Body.String())
552		}
553		json.Unmarshal(next.Body.Bytes(), &body)
554		if body["order"] != float64(2) {
555			t.Fatalf("order after retry = %v, want 2", body["order"])
556		}
557	}
