		{"chinese value", "cn-val", `{"mode": "拦截"}`, map[string]any{"mode": "拦截"}},
		{"literal null string", "literal-null", `{"mode": "null"}`, map[string]any{"mode": "null"}},
		{"mixed empty and non-empty", "mixed", `{"a": "", "b": "enforce"}`, map[string]any{"a": "", "b": "enforce"}},
	}
