15	)
16	
17	// policyWithRules builds a registration body with explicit rules and
18	// pluginParams JSON fragments.
19	func policyWithRules(ns, name, label, rulesJSON, paramsJSON string) string {
20		return fmt.Sprintf(`{
21			"namespace": %q,
22			"name": %q,
23			"label": %q,
24			"rules": %s,
25			"pluginParams": %s
26		}`, ns, name, label, rulesJSON, paramsJSON)
27	}
28	
29	// singleRuleBody builds a registration body holding exactly one rule.
30	func singleRuleBody(ns, name, label, direction, action string, lo, hi int, paramsJSON string) string {
31		return policyWithRules(ns, name, label,
32			fmt.Sprintf(`[{"direction": %q, "action": %q, "ports": [%d, %d]}]`, direction, action, lo, hi),
33			paramsJSON)
34	}
35	
36	// wantRecord derives the expected response object from the request body: every
37	// submitted field verbatim plus the registry metadata.
38	func wantRecord(t *testing.T, requestBody string, order int64, conflict bool) map[string]any {
39		t.Helper()
40		var record map[string]any
41		if err := json.Unmarshal([]byte(requestBody), &record); err != nil {
42			t.Fatalf("decode request body: %v", err)
43		}
44		record["order"] = float64(order)
45		record["conflict"] = conflict
46		return record
47	}
48	
49	// registerCreated posts the body, demands 201, and verifies the response
50	// carries every submitted field plus the expected order and conflict flag.
51	// It returns the decoded record for later comparisons.
52	func registerCreated(t *testing.T, router *gin.Engine, body string, wantOrder int64, wantConflict bool) map[string]any {
53		t.Helper()
54		recorder := doRequest(router, http.MethodPost, "/v1/net-policies", body)
55		if recorder.Code != http.StatusCreated {
56			t.Fatalf("status = %d, want %d: %s", recorder.Code, http.StatusCreated, recorder.Body.String())
57		}
58		var resp map[string]any
59		if err := json.Unmarshal(recorder.Body.Bytes(), &resp); err != nil {
60			t.Fatalf("decode: %v", err)
61		}
62		want := wantRecord(t, body, wantOrder, wantConflict)
63		if !reflect.DeepEqual(resp, want) {
64			t.Fatalf("record = %v, want %v", resp, want)
65		}
66		return resp
67	}
68	
69	// assertExactErrorShape verifies the body is exactly {"error":{"code","message"}}
70	// with both members being strings, and the code matching the contract.
71	func assertExactErrorShape(t *testing.T, recorder *httptest.ResponseRecorder, wantCode string) {
72		t.Helper()
73		var top map[string]json.RawMessage
74		if err := json.Unmarshal(recorder.Body.Bytes(), &top); err != nil {
75			t.Fatalf("decode error body: %v", err)
76		}
77		if len(top) != 1 {
78			t.Fatalf("error body has %d top-level keys, want exactly one (error): %s", len(top), recorder.Body.String())
79		}
80		raw, ok := top["error"]
81		if !ok {
82			t.Fatalf("error body missing top-level error object: %s", recorder.Body.String())
83		}
84		var errObj map[string]json.RawMessage
85		if err := json.Unmarshal(raw, &errObj); err != nil {
86			t.Fatalf("error member is not an object: %v", err)
87		}
88		if len(errObj) != 2 {
89			t.Fatalf("error object has %d members, want exactly code and message: %s", len(errObj), recorder.Body.String())
90		}
91		var code, message string
92		if err := json.Unmarshal(errObj["code"], &code); err != nil {
93			t.Fatalf("error.code is not a string: %s", recorder.Body.String())
94		}
95		if err := json.Unmarshal(errObj["message"], &message); err != nil {
96			t.Fatalf("error.message is not a string: %s", recorder.Body.String())
97		}
98		if code != wantCode {
99			t.Fatalf("error.code = %q, want %q", code, wantCode)
100		}
101		if message == "" {
102			t.Fatalf("error.message is empty: %s", recorder.Body.String())
103		}
104	}
105	
106	// The core lifecycle: a first policy in an empty history is conflict-free, a
107	// later opposite-action policy whose port interval touches the first at the
108	// endpoint is flagged, and the flag of the older record is not rewritten.
109	// Every query filter then returns the same records the registrations returned.
110	func TestConflictLifecycleAcrossRegisterAndQuery(t *testing.T) {
111		router, _ := newTestRouter(t)
112	
113		seedBody := singleRuleBody("payments", "deny-web", "tier=backend", "ingress", "deny", 80, 100, `{"mode": "enforce"}`)
114		seed := registerCreated(t, router, seedBody, 1, false)
115	
116		// Intervals [80,100] and [100,200] touch at endpoint 100: that counts as
117		// overlapping, so the opposite-action record is flagged.
118		clashBody := singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200, `{"mode": "enforce"}`)
119		clash := registerCreated(t, router, clashBody, 2, true)
120	
121		want := []map[string]any{seed, clash}
122		for _, target := range []string{
123			"/v1/net-policies?namespace=payments",
124			"/v1/net-policies?label=tier%3Dbackend",
125			"/v1/net-policies?namespace=payments&label=tier%3Dbackend",
126		} {
127			items := listItems(t, router, target)
128			if !reflect.DeepEqual(items, want) {
129				t.Fatalf("GET %s items = %v, want %v (older record keeps conflict=false, order ascending)", target, items, want)
130			}
131		}
132	}
133	
134	// Port overlap is decided on closed intervals: a single shared port, the
135	// boundary ports 1 and 65535, and intervals merely touching at an endpoint all
136	// count as overlapping; fully separated intervals do not.
137	func TestConflictPortBoundaries(t *testing.T) {
138		cases := []struct {
139			name                           string
140			seedLo, seedHi, candLo, candHi int
141			conflict                       bool
142		}{
143			{"single shared port", 53, 53, 53, 53, true},
144			{"touching at lower bound 1", 1, 1, 1, 65535, true},
145			{"touching at upper bound 65535", 65535, 65535, 1, 65535, true},
146			{"intervals touching at endpoint", 1, 100, 100, 65535, true},
147			{"fully separated ports", 1, 99, 100, 200, false},
148		}
149		router, _ := newTestRouter(t)
150		for i, tc := range cases {
151			t.Run(tc.name, func(t *testing.T) {
152				ns := fmt.Sprintf("ns-%d", i)
153				seedBody := singleRuleBody(ns, "seed", "tier=backend", "ingress", "deny", tc.seedLo, tc.seedHi, `{}`)
154				registerCreated(t, router, seedBody, int64(2*i+1), false)
155				candBody := singleRuleBody(ns, "candidate", "tier=backend", "ingress", "allow", tc.candLo, tc.candHi, `{}`)
156				registerCreated(t, router, candBody, int64(2*i+2), tc.conflict)
157			})
158		}
159	}
160	
161	// A clashing rule is found even when it sits behind other rules: the seed
