	retryBody := singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200,
		`{"zone": "east", "mode": "enforce"}`)
	recorder = doRequest(router, http.MethodPost, "/v1/net-policies", retryBody)
	if recorder.Code != http.StatusOK {
